+			rkey: item.rkey,
+			record: item.record,
+			validate: false,
+		}),
+	});
+}
+
+function argumentValue(prefix: string): string | undefined {
+	return process.argv.find((argument) => argument.startsWith(`${prefix}=`))?.slice(prefix.length + 1);
+}
